import React, { useState, useEffect } from 'react';
import { api } from '../api'; // Убедись, что импорт api правильный

const ProductModal = ({ isOpen, onClose, onSubmit, initialData }) => {
    const [file, setFile] = useState(null);
    const [formData, setFormData] = useState({
        title: '', category: 'GPU', price: '', description: '', stock: '0', image: ''
    });

    useEffect(() => {
        if (initialData) setFormData(initialData);
        else setFormData({ title: '', category: 'GPU', price: '', description: '', stock: '0', image: '' });
    }, [initialData, isOpen]);

    if (!isOpen) return null;

    const handleFormSubmit = async (e) => {
        e.preventDefault();
        let finalImageUrl = formData.image;

        if (file) {
            try {
                finalImageUrl = await api.uploadImage(file);
            } catch (err) {
                console.error("Ошибка загрузки:", err);
                alert("Не удалось загрузить фото");
            }
        }
        onSubmit({ ...formData, image: finalImageUrl });
    };

    return (
        <div className="modal-overlay">
            <div className="modal-content">
                <h2>{initialData ? 'Редактировать' : 'Добавить товар'}</h2>
                <form onSubmit={handleFormSubmit}>
                    <input 
                        type="text" placeholder="Название" required
                        value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} 
                    />
                    <input 
                        type="file" accept="image/*" 
                        onChange={e => setFile(e.target.files[0])} 
                    />
                    <div className="modal-actions">
                        <button type="button" onClick={onClose}>Отмена</button>
                        <button type="submit" className="save-btn">Сохранить</button>
                    </div>
                </form>
            </div>
        </div>
    );
};

// ВОТ ЭТА СТРОЧКА ИСПРАВИТ ПЕРВУЮ ОШИБКУ:
export default ProductModal;
